mapper.update:
UPDATE environment_sandboxes SET manager_version=#{version}
WHERE organization_uuid=#{target.OrganizationUUID} AND workspace_uuid=#{target.WorkspaceUUID}
    AND uuid=#{target.SandboxUUID} AND state IN ('creating','running')

mapper.select:
SELECT NOT EXISTS (SELECT 1 FROM sandbox_tool_calls
    WHERE organization_uuid=#{target.OrganizationUUID} AND workspace_uuid=#{target.WorkspaceUUID}
        AND sandbox_uuid=#{target.SandboxUUID}
        AND state IN ('dispatched','running','cancel_requested','finalizing')) AS idle
